"use client";

import { useEffect, useState, useMemo, useCallback } from "react";
import DeckGL from "@deck.gl/react";
import { Map } from "react-map-gl/maplibre";
import { ScatterplotLayer, ArcLayer, TextLayer } from "@deck.gl/layers";
import Papa from "papaparse";
import { X } from "lucide-react";
import "./App.css";

// Constants
const KAIST_LOCATION = {
  longitude: 127.363101,
  latitude: 36.373279,
  country: "Korea",
  institution: "KAIST\nTHEN Lab",
  website: "https://sites.google.com/view/thenlab",
};

const INITIAL_VIEW_STATE = {
  latitude: KAIST_LOCATION.latitude,
  longitude: KAIST_LOCATION.longitude,
  zoom: 5,
  bearing: 0,
  pitch: 45,
  maxZoom: 14,
  minZoom: 4,
};

const MAP_STYLE =
  "https://basemaps.cartocdn.com/gl/dark-matter-gl-style/style.json";

function App() {
  const [data, setData] = useState([]);
  const [tooltip, setTooltip] = useState(null);
  const [stats, setStats] = useState({ total: 0, countries: 0 });
  const [viewState, setViewState] = useState(INITIAL_VIEW_STATE);
  const [searchQuery, setSearchQuery] = useState("");
  const [showStats, setShowStats] = useState(true);

  // Load CSV data
  useEffect(() => {
    fetch(`${process.env.PUBLIC_URL}/data.csv`)
      .then((response) => response.text())
      .then((csvText) => {
        const parsed = Papa.parse(csvText, {
          header: true,
          dynamicTyping: true,
          skipEmptyLines: true,
        });
        const validData = parsed.data.filter(
          (d) => d.lon !== undefined && d.lat !== undefined
        );

        // Calculate statistics
        const uniqueCountries = new Set(validData.map((d) => d.country)).size;
        setStats({
          total: validData.length - 1,
          countries: uniqueCountries - 1,
        });

        setData(validData);
      })
      .catch((error) => console.error("Error loading data:", error));
  }, []);

  // Handle hover events (unless tooltip is pinned)
  const handleHover = useCallback(
    ({ object, x, y }) => {
      if (tooltip && tooltip.pinned) return;
      setTooltip(object ? { x, y, ...object, pinned: false } : null);
    },
    [tooltip]
  );

  // Handle click events to pin the tooltip
  const handleClick = useCallback(({ object, x, y }) => {
    if (object) {
      setTooltip({ x, y, ...object, pinned: true });
    }
  }, []);

  // Filter search results
  const searchResults = useMemo(() => {
    if (!searchQuery) return [];
    return data.filter((d) =>
      d.institution.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [data, searchQuery]);

  // Create layers
  const layers = useMemo(() => {
    const arcData = data.map((d) => ({
      sourcePosition: [KAIST_LOCATION.longitude, KAIST_LOCATION.latitude],
      targetPosition: [d.lon, d.lat],
      country: d.country,
      institution: d.institution,
    }));

    const arcLayer = new ArcLayer({
      id: "arc-layer",
      data: arcData,
      getSourcePosition: (d) => d.sourcePosition,
      getTargetPosition: (d) => d.targetPosition,
      getSourceColor: [64, 224, 208, 100],
      getTargetColor: [255, 99, 71, 100],
      getWidth: 10,
      getHeight: 0.1,
      greatCircle: true,
      widthMinPixels: 2,
      widthMaxPixels: 4,
      opacity: 0.3,
      pickable: true,
      autoHighlight: true,
      highlightColor: [255, 255, 255, 128],
      parameters: {
        depthTest: false,
      },
    });

    const destinationLayer = new ScatterplotLayer({
      id: "destination-layer",
      data,
      getPosition: (d) => [d.lon, d.lat],
      getFillColor: [255, 99, 71, 200],
      getRadius: 6,
      radiusUnits: "pixels",
      pickable: true,
      onHover: handleHover,
      onClick: handleClick,
    });

    const kaistLayer = new ScatterplotLayer({
      id: "kaist-point",
      data: [KAIST_LOCATION],
      getPosition: (d) => [d.longitude, d.latitude],
      getFillColor: [64, 224, 208, 255],
      getRadius: 10,
      radiusUnits: "pixels",
      pickable: true,
      onHover: handleHover,
      onClick: handleClick,
    });

    const labelLayer = new TextLayer({
      id: "text-layer",
      data: [KAIST_LOCATION],
      getPosition: (d) => [d.longitude, d.latitude],
      getText: (d) => d.institution,
      getSize: 20,
      getColor: [255, 255, 255],
      getTextAnchor: "middle",
      getAlignmentBaseline: "center",
      getPixelOffset: [0, 30],
      background: true,
      getBackgroundColor: [0, 0, 0, 180],
      getBorderWidth: 1,
      getBorderColor: [255, 255, 255, 255],
      billboard: true,
    });

    return [labelLayer, arcLayer, destinationLayer, kaistLayer];
  }, [data, handleHover, handleClick]);

  return (
    <div className="relative h-screen w-screen">
      <DeckGL
        layers={layers}
        viewState={viewState}
        onViewStateChange={({ viewState }) => setViewState(viewState)}
        controller={true}
        pickingRadius={20}
      >
        <Map
          reuseMaps
          mapStyle={MAP_STYLE}
          style={{ width: "100%", height: "100%" }}
        />
        {tooltip && (
          <div
            className="tooltip"
            style={{
              position: "absolute",
              left: tooltip.x + 10,
              top: tooltip.y + 10,
              pointerEvents: tooltip.pinned ? "auto" : "none",
            }}
          >
            {tooltip.pinned && (
              <button
                className="tooltip-dismiss"
                onClick={() => setTooltip(null)}
              >
                <X size={16} />
              </button>
            )}
            <div>
              <div className="tooltip-label">Country</div>
              <div className="tooltip-value">{tooltip.country}</div>
              <div className="tooltip-label">Institution</div>
              <div className="tooltip-value">{tooltip.institution}</div>
              <div className="tooltip-label">Website</div>
              <div className="tooltip-value">
                <a
                  href={tooltip.website}
                  className="text-white hover:text-blue-300"
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  {tooltip.website}
                </a>
              </div>
            </div>
          </div>
        )}
      </DeckGL>

      {/* Grouped Search and Statistics Overlay */}
      <div className="absolute top-[45%] right-4 space-y-4 max-w-[300px] min-w-[300px]">
        {/* Search Widget */}
        <div className="bg-black bg-opacity-85 p-4 rounded-lg backdrop-blur-md border border-white border-opacity-10 shadow-lg">
          <input
            type="text"
            placeholder="Search institution..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full p-2 bg-gray-800 text-white rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
          {searchResults.length > 0 && (
            <ul className="mt-2 bg-gray-800 rounded-md max-h-48 overflow-y-auto scrollbar-thin scrollbar-thumb-gray-600 scrollbar-track-gray-900">
              {searchResults.map((inst, idx) => (
                <li
                  key={idx}
                  onClick={() => {
                    setViewState((prev) => ({
                      ...prev,
                      latitude: inst.lat,
                      longitude: inst.lon,
                      zoom: 14,
                    }));
                    setTooltip({
                      x: window.innerWidth / 2 - 100,
                      y: window.innerHeight / 2 - 100,
                      ...inst,
                      pinned: true,
                    });
                    setSearchQuery(""); // reset search bar after moving
                  }}
                  className="p-2 hover:bg-gray-700 cursor-pointer text-white"
                >
                  {inst.institution}
                </li>
              ))}
            </ul>
          )}
        </div>

        {/* Statistics Overlay */}
        {showStats && (
          <div className="bg-black bg-opacity-85 p-4 rounded-lg backdrop-blur-md border border-white border-opacity-10 shadow-lg relative">
            <button
              className="absolute top-2 right-2 text-white hover:text-red-500"
              onClick={() => setShowStats(false)}
            >
              <X size={16} />
            </button>
            <div className="text-blue-400 font-semibold mb-2 uppercase tracking-wide text-sm">
              Statistics
            </div>
            <div className="flex justify-between mb-1">
              <span className="text-gray-400 text-sm">Total Institutions</span>
              <span className="text-white font-medium">{stats.total}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-gray-400 text-sm">Countries</span>
              <span className="text-white font-medium">{stats.countries}</span>
            </div>
          </div>
        )}
      </div>

      <footer className="absolute bottom-0 w-full bg-black bg-opacity-85 text-white text-center py-3 text-sm leading-relaxed backdrop-blur-md border-t border-white border-opacity-10">
        2024 ANU-GPC Glocal University Project (PI: Donghyun Woo, KAIST)
        <br />
        Developed by{" "}
        <a
          href="https://dh-choi.com"
          className="text-blue-400 hover:text-blue-300"
        >
          Donghyeok Choi
        </a>{" "}
        - The University of Hong Kong
      </footer>
    </div>
  );
}

export default App;
